/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    let uploadCode = (String(($c.data.readValue("dma_pageContext", "uploadCode", { ctx: true, soft: true, label: "uploadCode" })) == null ? '' : ($c.data.readValue("dma_pageContext", "uploadCode", { ctx: true, soft: true, label: "uploadCode" }))).indexOf('$' + '{') >= 0 ? '' : String(($c.data.readValue("dma_pageContext", "uploadCode", { ctx: true, soft: true, label: "uploadCode" })) == null ? '' : ($c.data.readValue("dma_pageContext", "uploadCode", { ctx: true, soft: true, label: "uploadCode" }))));
    let prtDepoNo = (String(($c.data.readValue("dma_pageContext", "prtDepoNo", { ctx: true, soft: true, label: "prtDepoNo" })) == null ? '' : ($c.data.readValue("dma_pageContext", "prtDepoNo", { ctx: true, soft: true, label: "prtDepoNo" }))).indexOf('$' + '{') >= 0 ? '' : String(($c.data.readValue("dma_pageContext", "prtDepoNo", { ctx: true, soft: true, label: "prtDepoNo" })) == null ? '' : ($c.data.readValue("dma_pageContext", "prtDepoNo", { ctx: true, soft: true, label: "prtDepoNo" }))));
    let searchType = (String(($c.data.readValue("dma_pageContext", "searchType", { ctx: true, soft: true, label: "searchType" })) == null ? '' : ($c.data.readValue("dma_pageContext", "searchType", { ctx: true, soft: true, label: "searchType" }))).indexOf('$' + '{') >= 0 ? '' : String(($c.data.readValue("dma_pageContext", "searchType", { ctx: true, soft: true, label: "searchType" })) == null ? '' : ($c.data.readValue("dma_pageContext", "searchType", { ctx: true, soft: true, label: "searchType" }))));
    if (searchType !== '' && searchType !== '0') {
        if (uploadCode === '0') {
            await $c.win.alert('저장되었습니다.');
        } else {
            if (uploadCode === '1') {
                await $c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
            } else {
                if (uploadCode === '2') {
                    await $c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
                } else {
                    if (prtDepoNo === '') {
                        await $c.win.alert('저장시 오류가 발생하였습니다.');
                    }
                }
            }
        }
    }
};


